from hermes_tools import write_file
import json
from datetime import datetime, timedelta
import random

# Generate sample nested API responses (mimicking a real-world e-commerce API)
def generate_mock_api_responses():
    """Generate realistic nested API data for demonstration"""

    products = [
        {"id": "P001", "name": "Wireless Headphones", "category": "Electronics", "price": 79.99},
        {"id": "P002", "name": "Running Shoes", "category": "Sports", "price": 120.00},
        {"id": "P003", "name": "Coffee Maker", "category": "Home", "price": 45.50},
        {"id": "P004", "name": "Yoga Mat", "category": "Sports", "price": 25.00},
        {"id": "P005", "name": "Bluetooth Speaker", "category": "Electronics", "price": 55.99},
    ]

    base_date = datetime(2024, 1, 15)

    # Create deeply nested API response structure
    api_responses = []
    for i in range(20):
        product = random.choice(products)
        order_date = base_date + timedelta(days=i, hours=random.randint(0, 23))

        response = {
            "metadata": {
                "request_id": f"REQ-{1000 + i}",
                "timestamp": order_date.isoformat() + "Z",
                "api_version": "2.1"
            },
            "order": {
                "order_id": f"ORD-{5000 + i}",
                "customer": {
                    "customer_id": f"CUST-{10000 + (i % 5)}",
                    "name": f"Customer_{i % 5}",
                    "email": f"customer{i%5}@example.com",
                    "address": {
                        "street": f"{random.randint(100, 999)} Main St",
                        "city": random.choice(["New York", "Los Angeles", "Chicago", "Houston", "Phoenix"]),
                        "zip": f"{random.randint(10000, 99999)}"
                    }
                },
                "items": [
                    {
                        "product": product,
                        "quantity": random.randint(1, 5),
                        "discount": {
                            "type": random.choice(["percentage", "fixed", None]),
                            "value": random.choice([10, 20, 5, None])
                        }
                    }
                ],
                "payment": {
                    "method": random.choice(["credit_card", "paypal", "debit_card"]),
                    "transaction_id": f"TXN-{100000 + i}",
                    "status": random.choice(["completed", "pending", "failed"])
                },
                "shipping": {
                    "method": random.choice(["standard", "express", "overnight"]),
                    "cost": round(random.uniform(5, 25), 2),
                    "estimated_delivery": (order_date + timedelta(days=random.randint(3, 10))).strftime("%Y-%m-%d")
                }
            },
            "calculated": {
                "subtotal": 0,
                "tax_rate": 0.08,
                "total": 0
            }
        }

        # Calculate totals
        item = response["order"]["items"][0]
        subtotal = item["product"]["price"] * item["quantity"]
        discount = 0
        if item["discount"]["value"]:
            if item["discount"]["type"] == "percentage":
                discount = subtotal * (item["discount"]["value"] / 100)
            else:
                discount = item["discount"]["value"]

        response["calculated"]["subtotal"] = round(subtotal, 2)
        response["calculated"]["total"] = round(subtotal - discount + response["order"]["shipping"]["cost"], 2)

        api_responses.append(response)

    return api_responses

# Generate the mock data
raw_data = generate_mock_api_responses()

# Save raw data for reference
write_file("raw_api_responses.json", json.dumps(raw_data, indent=2))
print(f"✓ Generated {len(raw_data)} mock API responses")
print(f"✓ Saved raw data to: raw_api_responses.json")

