        function generateMetric(base, variance) {
            return Math.round((base + (Math.random() - 0.5) * variance) * 10) / 10;
        }

        function getStatusClass(value, warning, critical) {
            if (value >= critical) return 'danger';
            if (value >= warning) return 'warning';
            return 'success';
        }

        function updateDashboard() {
            const now = new Date();
            const timeLabel = now.toLocaleTimeString();

            // Generate simulated metrics
            const cpu = generateMetric(45, 20);
            const memory = generateMetric(60, 15);
            const disk = generateMetric(55, 5);
            const download = generateMetric(25, 10);
            const upload = generateMetric(8, 5);

            // Update metric cards
            document.getElementById('cpuValue').textContent = cpu.toFixed(1) + '%';
            document.getElementById('cpuValue').className = 'metric-value ' + getStatusClass(cpu, 80, 95);
            document.getElementById('cpuTrend').textContent = Math.random() > 0.5 ? '↑ Stable' : '↓ Fluctuating';
            document.getElementById('cpuTrend').className = 'metric-change ' + (cpu > 80 ? 'negative' : 'positive');

            document.getElementById('memValue').textContent = memory.toFixed(1) + '%';
            document.getElementById('memValue').className = 'metric-value ' + getStatusClass(memory, 85, 95);
            document.getElementById('memTrend').textContent = (memory * 0.16).toFixed(1) + ' GB / 16 GB';

            document.getElementById('diskValue').textContent = disk.toFixed(1) + '%';
            document.getElementById('diskValue').className = 'metric-value ' + getStatusClass(disk, 85, 95);
            document.getElementById('diskTrend').textContent = '55 GB free';

            document.getElementById('networkValue').textContent = (download + upload).toFixed(1) + ' MB/s';
            document.getElementById('networkTrend').textContent = '↓' + download.toFixed(1) + ' ↑' + upload.toFixed(1);

            // Update charts
            if (metricsChart.data.labels.length >= maxDataPoints) {
                metricsChart.data.labels.shift();
                metricsChart.data.datasets.forEach(dataset => dataset.data.shift());
            }

            metricsChart.data.labels.push(timeLabel);
            metricsChart.data.datasets[0].data.push(cpu);
            metricsChart.data.datasets[1].data.push(memory);
            metricsChart.data.datasets[2].data.push(disk);
            metricsChart.update('none');

            if (networkChart.data.labels.length >= maxDataPoints) {
                networkChart.data.labels.shift();
                networkChart.data.datasets.forEach(dataset => dataset.data.shift());
            }

            networkChart.data.labels.push(timeLabel);
            networkChart.data.datasets[0].data.push(download);
            networkChart.data.datasets[1].data.push(upload);
            networkChart.update('none');

            // Simulate alerts
            if (Math.random() < 0.1 && alerts.length < 5) {
                const alertTypes = [
                    { severity: 'warning', message: 'High CPU usage detected', icon: '⚠️' },
                    { severity: 'critical', message: 'Service health check failed', icon: '🔥' },
                    { severity: 'info', message: 'Disk cleanup completed', icon: 'ℹ️' }
                ];
                const alert = alertTypes[Math.floor(Math.random() * alertTypes.length)];
                alerts.push({
                    id: Date.now(),
                    ...alert,
                    time: timeLabel
                });
                updateAlerts();
            }

            // Update timestamp
            document.getElementById('lastUpdate').textContent = 'Updated: ' + timeLabel;
        }

        function updateAlerts() {
            const alertCount = document.getElementById('alertCount');
            const alertsList = document.getElementById('alertsList');

            alertCount.textContent = alerts.length;

            if (alerts.length === 0) {
                alertsList.innerHTML = `
                    <div style="text-align: center; padding: 2rem; color: var(--text-secondary);">
                        No active alerts at this time
                    </div>
                `;
                alertCount.style.background = '#10b981';
            } else {
                alertCount.style.background = alerts.some(a => a.severity === 'critical') ? '#ef4444' : '#f59e0b';
                alertsList.innerHTML = alerts.map(alert => `
                    <div class="alert-item ${alert.severity}">
                        <span class="alert-icon">${alert.icon}</span>
                        <div class="alert-content">
                            <div class="alert-message">${alert.message}</div>
                            <div class="alert-time">${alert.time}</div>
                        </div>
                        <div class="alert-actions">
                            <button class="btn btn-ack" onclick="ackAlert(${alert.id})">Ack</button>
                            <button class="btn btn-resolve" onclick="resolveAlert(${alert.id})">Resolve</button>
                        </div>
                    </div>
                `).join('');
            }
        }

        function ackAlert(id) {
            console.log('Acknowledged alert:', id);
        }

        function resolveAlert(id) {
            alerts = alerts.filter(a => a.id !== id);
            updateAlerts();
            addLog('SUCCESS', `Alert ${id} resolved by user`);
        }

        function addLog(level, message) {
            const log = document.getElementById('remediationLog');
            const time = new Date().toLocaleTimeString();
            const entry = document.createElement('div');
            entry.className = 'log-entry';
            entry.innerHTML = `
                <span class="log-time">${time}</span>
                <span class="log-${level.toLowerCase()}">[${level}]</span>
                <span>${message}</span>
            `;
            log.insertBefore(entry, log.firstChild);
            if (log.children.length > 20) {
                log.removeChild(log.lastChild);
            }
        }

        // Simulate remediation actions
        function simulateRemediation() {
            if (alerts.some(a => a.message.includes('CPU'))) {
                setTimeout(() => {
                    addLog('INFO', 'Auto-remediation: Restarted service nginx to reduce CPU load');
                    alerts = alerts.filter(a => !a.message.includes('CPU'));
                    updateAlerts();
                }, 5000);
            }
        }

        // Initial load
        updateDashboard();

        // Refresh every 5 seconds
        setInterval(() => {
            updateDashboard();
            simulateRemediation();
        }, 5000);

        // Add some initial remediation logs
        setTimeout(() => addLog('INFO', 'Monitoring collector initialized'), 1000);
        setTimeout(() => addLog('SUCCESS', 'Connected to Prometheus backend'), 2000);
        setTimeout(() => addLog('INFO', 'Alert rules loaded: 9 active'), 3000);
    </script>
</body>
</html>
'''

