<body>
    <header class="header">
        <h1>Monitoring Dashboard</h1>
        <div class="status-bar">
            <div class="status-indicator">
                <span class="status-dot online"></span>
                <span>Live</span>
            </div>
            <span class="last-update" id="lastUpdate">--:--:--</span>
        </div>
    </header>

    <div class="container">
        <div class="metrics-grid">
            <div class="metric-card">
                <div class="metric-header">
                    <span class="metric-title">CPU Usage</span>
                    <span class="metric-status" id="cpuStatus" style="background:#10b981;"></span>
                </div>
                <div class="metric-value success" id="cpuValue">--%</div>
            </div>
            <div class="metric-card">
                <div class="metric-header">
                    <span class="metric-title">Memory Usage</span>
                    <span class="metric-status" id="memStatus" style="background:#10b981;"></span>
                </div>
                <div class="metric-value success" id="memValue">--%</div>
            </div>
            <div class="metric-card">
                <div class="metric-header">
                    <span class="metric-title">Disk Usage</span>
                    <span class="metric-status" id="diskStatus" style="background:#10b981;"></span>
                </div>
                <div class="metric-value success" id="diskValue">--%</div>
            </div>
            <div class="metric-card">
                <div class="metric-header">
                    <span class="metric-title">Network</span>
                    <span class="metric-status" id="netStatus" style="background:#10b981;"></span>
                </div>
                <div class="metric-value success" id="networkValue">--</div>
            </div>
        </div>

        <div class="chart-container">
            <div class="chart-header">
                <span class="chart-title">System Metrics</span>
            </div>
            <div class="chart-wrapper">
                <canvas id="metricsChart"></canvas>
            </div>
        </div>

        <div class="alerts-section">
            <div class="chart-header">
                <span class="chart-title">Active Alerts</span>
                <span id="alertCount" style="background:#ef4444;color:white;padding:0.25rem 0.75rem;border-radius:999px;">0</span>
            </div>
            <div id="alertsList">
                <div style="text-align:center;padding:2rem;color:var(--text-secondary);">No active alerts</div>
            </div>
        </div>

        <div class="remediation-log">
            <div class="chart-header">
                <span class="chart-title">Remediation Log</span>
            </div>
            <div id="remediationLog"></div>
        </div>
    </div>

    <script>
        const ctx = document.getElementById('metricsChart').getContext('2d');
        const chart = new Chart(ctx, {
            type: 'line',
            data: {
                labels: [],
                datasets: [
                    { label: 'CPU %', data: [], borderColor: '#3b82f6', tension: 0.4 },
                    { label: 'Memory %', data: [], borderColor: '#10b981', tension: 0.4 },
                    { label: 'Disk %', data: [], borderColor: '#f59e0b', tension: 0.4 }
                ]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                interaction: { mode: 'index', intersect: false },
                scales: {
                    x: { grid: { color: '#334155' }, ticks: { color: '#94a3b8' } },
                    y: { grid: { color: '#334155' }, ticks: { color: '#94a3b8' }, min: 0, max: 100 }
                },
                plugins: { legend: { labels: { color: '#94a3b8' } } }
            }
        });

        let alerts = [];

        function rand(base, var_) {
            return Math.max(0, Math.min(100, base + (Math.random() - 0.5) * var_));
        }

        function statusColor(v, w, c) {
            return v >= c ? '#ef4444' : v >= w ? '#f59e0b' : '#10b981';
        }

        function update() {
            const now = new Date().toLocaleTimeString();
            const cpu = rand(45, 30), mem = rand(60, 20), disk = rand(55, 10);

            document.getElementById('cpuValue').textContent = cpu.toFixed(1) + '%';
            document.getElementById('cpuValue').className = 'metric-value ' + (cpu >= 95 ? 'danger' : cpu >= 80 ? 'warning' : 'success');
            document.getElementById('cpuStatus').style.background = statusColor(cpu, 80, 95);

            document.getElementById('memValue').textContent = mem.toFixed(1) + '%';
            document.getElementById('memValue').className = 'metric-value ' + (mem >= 95 ? 'danger' : mem >= 85 ? 'warning' : 'success');
            document.getElementById('memStatus').style.background = statusColor(mem, 85, 95);

            document.getElementById('diskValue').textContent = disk.toFixed(1) + '%';
            document.getElementById('diskStatus').style.background = statusColor(disk, 85, 95);

            document.getElementById('networkValue').textContent = (rand(20, 10)).toFixed(1) + ' MB/s';

            if (chart.data.labels.length >= 20) {
                chart.data.labels.shift();
                chart.data.datasets.forEach(d => d.data.shift());
            }
            chart.data.labels.push(now);
            chart.data.datasets[0].data.push(cpu);
            chart.data.datasets[1].data.push(mem);
            chart.data.datasets[2].data.push(disk);
            chart.update('none');

            document.getElementById('lastUpdate').textContent = now;

            if (Math.random() < 0.08 && alerts.length < 3) {
                const types = [
                    { s: 'warning', m: 'High CPU detected' },
                    { s: 'critical', m: 'Service down' },
                    { s: 'info', m: 'Auto-remediation completed' }
                ];
                const t = types[Math.floor(Math.random() * types.length)];
                alerts.push({ id: Date.now(), ...t, time: now });
                updateAlerts();
            }
        }

        function updateAlerts() {
            document.getElementById('alertCount').textContent = alerts.length;
            const list = document.getElementById('alertsList');
            if (alerts.length === 0) {
                list.innerHTML = '<div style="text-align:center;padding:2rem;color:var(--text-secondary);">No active alerts</div>';
            } else {
                list.innerHTML = alerts.map(a => `
                    <div class="alert-item ${a.s}">
                        <span>${a.m}</span>
                        <span style="color:var(--text-secondary);font-size:0.8rem;">${a.time}</span>
                        <button class="btn btn-ack" onclick="ack(${a.id})">Ack</button>
                        <button class="btn btn-res" onclick="res(${a.id})">Resolve</button>
                    </div>
                `).join('');
            }
        }

        function ack(id) { console.log('Ack', id); }
        function res(id) {
            alerts = alerts.filter(a => a.id !== id);
            updateAlerts();
            addLog('REMEDIATION: Alert ' + id + ' resolved');
        }

        function addLog(msg) {
            const log = document.getElementById('remediationLog');
            const entry = document.createElement('div');
            entry.className = 'log-entry';
            entry.innerHTML = `<span style="color:var(--text-secondary);">${new Date().toLocaleTimeString()}</span> ${msg}`;
            log.insertBefore(entry, log.firstChild);
            if (log.children.length > 15) log.removeChild(log.lastChild);
        }

        setInterval(update, 5000);
        update();
        addLog('Monitoring initialized');
        addLog('Connected to metrics backend');
    </script>
</body>
</html>
'''

