        auth_manager.register("user@example.com", "SecurePass123!")

        token1 = auth_manager.request_password_reset("user@example.com")
        token2 = auth_manager.request_password_reset("user@example.com")

        # Each request creates a new token
        assert token1.token_id != token2.token_id


class TestPasswordResetExecution:
    def test_reset_password_success(self, auth_manager, user_with_password_reset):
        user, token = user_with_password_reset
        old_hash = user.password_hash

        auth_manager.reset_password(token.token_id, "NewSecurePass456!")

        updated_user = auth_manager.get_user(user.user_id)
        assert updated_user.password_hash != old_hash

