class TestLockoutTrigger:
    def test_lockout_after_five_failures(self, auth_manager, registered_user):
        # 5 failed attempts
        for i in range(5):
            try:
                auth_manager.login("user@example.com", f"Wrong{i}!")
            except (InvalidCredentialsError, AccountLockedError):
                pass

        # 6th attempt should be locked
        with pytest.raises(AccountLockedError) as exc_info:
            auth_manager.login("user@example.com", "SecurePass123!")

        assert "locked" in str(exc_info.value).lower()

    def test_lockout_tracks_attempts(self, auth_manager, registered_user):
        for i in range(3):
            try:
                auth_manager.login("user@example.com", "Wrong!")
            except InvalidCredentialsError:
                pass

        user = auth_manager.get_user(registered_user.user_id)
        assert user.failed_login_attempts == 3


