import os
from pathlib import Path

def print_tree(path, prefix="", skip_dirs=None):
    if skip_dirs is None:
        skip_dirs = {".venv", "__pycache__", ".git", "*.pyc"}

    path = Path(path)
    if not path.exists():
        print(f"{path} does not exist")
        return

    items = sorted(path.iterdir(), key=lambda x: (x.is_file(), x.name.lower()))
    items = [i for i in items if not any(d in str(i) for d in skip_dirs)]

    for i, item in enumerate(items):
        is_last = i == len(items) - 1
        current_prefix = prefix + ("└── " if is_last else "├── ")

        print(f"{current_prefix}{item.name}")

        if item.is_dir():
            extension = "    " if is_last else "│   "
            print_tree(item, prefix + extension, skip_dirs)

