import os
from pathlib import Path

def print_tree(path, prefix="", skip_dirs=None, max_depth=15, current_depth=0):
    if skip_dirs is None:
        skip_dirs = {"__pycache__", ".git", ".venv", "node_modules"}

    path = Path(path)
    if not path.exists():
        print(f"Path does not exist: {path}")
        return

    if current_depth >= max_depth:
        return

    try:
        items = sorted(path.iterdir(), key=lambda x: (not x.is_dir(), x.name.lower()))
    except PermissionError:
        return

    # Filter
    filtered = []
    for item in items:
        if item.name.startswith('.') and item.name not in ['.github', '.gitignore']:
            continue
        if any(skip in str(item) for skip in skip_dirs):
            continue
        if item.suffix == '.pyc':
            continue
        filtered.append(item)

    for i, item in enumerate(filtered):
        is_last = i == len(filtered) - 1
        current_prefix = prefix + ("└── " if is_last else "├── ")

        print(f"{current_prefix}{item.name}")

        if item.is_dir():
            extension = "    " if is_last else "│   "
            print_tree(item, prefix + extension, skip_dirs, max_depth, current_depth + 1)

