# Parse name from frontmatter
name_pattern = re.compile(r'^name:\s*(.+)$', re.MULTILINE)
skills_by_name = {}

for sf in skill_files:
    try:
        with open(sf, 'r') as f:
            content = f.read()
        match = name_pattern.search(content)
