// Test file for data-tauri-drag-region="deep"

const TAURI_DRAG_REGION_ATTR = 'data-tauri-drag-region'
const CLICKABLE_TAGS = new Set([
  'A',
  'BUTTON',
  'INPUT',
  'SELECT',
  'TEXTAREA',
  'LABEL',
  'SUMMARY'
])
const INTERACTIVE_ROLES = new Set([
  'button',
  'link',
  'menuitem',
  'tab',
  'checkbox',
  'radio',
  'switch',
  'option'
])

function isClickableElement(el) {
  return (
    CLICKABLE_TAGS.has(el.tagName)
    || (el.hasAttribute('contenteditable')
      && el.getAttribute('contenteditable') !== 'false')
    || (el.hasAttribute('tabindex') && el.getAttribute('tabindex') !== '-1')
    || INTERACTIVE_ROLES.has(el.getAttribute('role'))
  )
}

function isDragRegion(composedPath) {
  for (const el of composedPath) {
    if (!(el instanceof HTMLElement)) continue

    const attr = el.getAttribute(TAURI_DRAG_REGION_ATTR)

    // clickable without explicit drag region → blocks drag
    if (isClickableElement(el) && attr === null) return false
    // no attr → keep walking up
    if (attr === null) continue
    // explicitly disabled
    if (attr === 'false') return false
    // subtree drag — any descendant triggers
    if (attr === 'deep') return true
    // bare or "true" attr — only direct clicks on this element
    if (attr === '' || attr === 'true') return el === composedPath[0]
  }

  return false
}

// Mock HTMLElement for testing
class MockElement {
  constructor(tagName, attrs = {}) {
    this.tagName = tagName.toUpperCase()
    this._attrs = attrs
    this._role = attrs.role || null
  }

  hasAttribute(name) {
    return name in this._attrs
  }

  getAttribute(name) {
    return this._attrs[name] !== undefined ? this._attrs[name] : null
  }
}

// Run tests
console.log('=== Testing isDragRegion function ===\n')

// Test 1: No drag region attribute
const noAttr = [new MockElement('div')]
