package javaguide.concurrent;

import sun.misc.Unsafe;
import java.lang.reflect.Field;

/**
 * 修正后的CAS示例代码
 * 修复了Issue#2650中提到的并发打印问题和livelock问题
 */
public class CasTestFixed {
    private volatile int a;
    private static Unsafe unsafe;
    private static long fieldOffset;

    static {
        try {
            // 通过反射获取 Unsafe 实例
            Field field = Unsafe.class.getDeclaredField("theUnsafe");
            field.setAccessible(true);
            unsafe = (Unsafe) field.get(null);
            // 获取字段偏移量（只需计算一次）
            fieldOffset = unsafe.objectFieldOffset(CasTestFixed.class.getDeclaredField("a"));
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) throws InterruptedException {
        // 运行10次测试，验证输出稳定性
        for (int run = 0; run < 10; run++) {
            System.out.println("\n=== 运行第 " + (run + 1) + " 次 ===");
            CasTestFixed casTest = new CasTestFixed();
            Thread t1 = new Thread(() -> {
                for (int i = 1; i < 5; i++) {
                    casTest.incrementAndPrint(i);
                }
            });
            Thread t2 = new Thread(() -> {
                for (int i = 5; i < 10; i++) {
                    casTest.incrementAndPrint(i);
                }
            });
            t1.start();
            t2.start();
            t1.join();
            t2.join();
            System.out.println();
        }
    }

    /**
     * 修正后的方法：将递增和打印操作封装在一个原子性更强的方法内
     * 解决并发打印问题和活锁问题
     * 
     * 修复要点：
     * 1. 解决并发打印问题：将打印操作放在 CAS 成功后的原子块内，
     *    确保打印的值就是当前线程成功设置的值。
     * 2. 解决活锁问题：使用动态读取的 currentValue 作为期望值，
     *    而不是固定的 x-1，这样即使线程执行顺序与预期不同也能正常工作。
     * 3. 优化字段偏移量计算：将 fieldOffset 的计算移到静态代码块中，
     *    避免每次调用方法时都重复反射获取字段，提高性能。
     */
    private void incrementAndPrint(int targetValue) {
        while (true) {
            int currentValue = a; // 读取当前 a 的值
            // 如果当前值已经达到或超过目标值，说明已被其他线程处理，跳过
            if (currentValue >= targetValue) {
                return;
            }
            // 尝试 CAS 操作：将当前值更新为目标值
            if (unsafe.compareAndSwapInt(this, fieldOffset, currentValue, targetValue)) {
                // CAS 成功后立即打印，确保打印的就是本次设置的值
                System.out.print(targetValue + " ");
                return;
            }
            // CAS 失败，重新读取并重试（自旋）
        }
    }
