func StringContains(s, substr string) bool {
	return len(substr) > 0 && len(s) >= len(substr) && 
		(s == substr || len(s) > 0 && containsSubstring(s, substr))
}

func containsSubstring(s, substr string) bool {
	for i := 0; i <= len(s)-len(substr); i++ {
		if s[i:i+len(substr)] == substr {
			return true
		}
	}
	return false
}

// Test basic function
func TestAdd(t *testing.T) {
	cases := []struct {
		a, b, expected int
	}{
		{2, 3, 5},
		{10, 20, 30},
		{0, 0, 0},
		{-1, 1, 0},
	}

	for _, tc := range cases {
		result := Add(tc.a, tc.b)
		if result != tc.expected {
			t.Errorf("Add(%d, %d) = %d; want %d", tc.a, tc.b, result, tc.expected)
		}
	}
}

// Test with subtests
func TestStringContains(t *testing.T) {
	tests := []struct {
		name     string
		s        string
		substr   string
		expected bool
	}{
		{"found", "Hello, World!", "World", true},
		{"not found", "Hello, World!", "Foo", false},
		{"empty substring", "Hello", "", false},
		{"same string", "Hello", "Hello", true},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := StringContains(tt.s, tt.substr)
			if result != tt.expected {
				t.Errorf("StringContains(%q, %q) = %v; want %v",
					tt.s, tt.substr, result, tt.expected)
			}
		})
	}
}

