from flask import Flask, jsonify, request
import json

app = Flask(__name__)

data_store = {
    1: {"id": 1, "name": "John Doe", "email": "john@example.com"},
    2: {"id": 2, "name": "Jane Smith", "email": "jane@example.com"}
}

@app.route('/health', methods=['GET'])
def health_check():
    """Health check endpoint"""
    return jsonify({"status": "healthy", "version": "1.0.0"})

@app.route('/users', methods=['GET'])
def get_users():
    """Get all users"""
    return jsonify(list(data_store.values()))

@app.route('/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get specific user by ID"""
    if user_id in data_store:
        return jsonify(data_store[user_id])
    return jsonify({"error": "User not found"}), 404

@app.route('/users', methods=['POST'])
def create_user():
    """Create a new user"""
    data = request.get_json()
    if not data or 'name' not in data or 'email' not in data:
        return jsonify({"error": "Name and email required"}), 400

    new_id = max(data_store.keys()) + 1 if data_store else 1
    new_user = {"id": new_id, "name": data['name'], "email": data['email']}
    data_store[new_id] = new_user
    return jsonify(new_user), 201

@app.route('/users/<int:user_id>', methods=['PUT'])
def update_user(user_id):
    """Update user by ID"""
    if user_id not in data_store:
        return jsonify({"error": "User not found"}), 404

    data = request.get_json()
    user = data_store[user_id]
    user['name'] = data.get('name', user['name'])
    user['email'] = data.get('email', user['email'])
    return jsonify(user)

@app.route('/users/<int:user_id>', methods=['DELETE'])
def delete_user(user_id):
    """Delete user by ID"""
    if user_id not in data_store:
        return jsonify({"error": "User not found"}), 404

    del data_store[user_id]
    return jsonify({"message": "User deleted"}), 200

if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0', port=5000)
