import { expect, afterEach, vi } from 'vitest'
import { cleanup } from '@testing-library/react'

// Extend Vitest's expect with custom matchers
expect.extend({
  toBeInTheDocument(received) {
    const pass = received !== null && received !== undefined
    return {
      pass,
      message: () => pass
        ? `expected element not to be in the document`
        : `expected element to be in the document`,
    }
  },
  toHaveTextContent(received, expected) {
    const text = received?.textContent || ''
    const pass = text.includes(expected)
    return {
      pass,
      message: () => pass
        ? `expected element not to have text content "${expected}"`
        : `expected element to have text content "${expected}", but got "${text}"`,
    }
  },
  toHaveClass(received, expected) {
    const className = received?.className || ''
    const classes = className.split(' ')
    const pass = classes.includes(expected)
    return {
      pass,
      message: () => pass
        ? `expected element not to have class "${expected}"`
        : `expected element to have class "${expected}"`,
    }
  },
})

