import { useState } from 'react'
import type { Todo, TodoFilter } from '../types'

export interface TodoListProps {
  initialTodos?: Todo[]
}

export function TodoList({ initialTodos = [] }: TodoListProps) {
  const [todos, setTodos] = useState<Todo[]>(initialTodos)
  const [newTodoTitle, setNewTodoTitle] = useState('')
  const [filter, setFilter] = useState<TodoFilter>({ status: 'all', priority: 'all' })
  const [editingId, setEditingId] = useState<string | null>(null)
  const [editTitle, setEditTitle] = useState('')

  const addTodo = () => {
    if (!newTodoTitle.trim()) return
    const todo: Todo = {
      id: Date.now().toString(),
      title: newTodoTitle,
      completed: false,
      createdAt: new Date(),
      priority: 'medium'
    }
    setTodos([...todos, todo])
    setNewTodoTitle('')
  }

  const toggleTodo = (id: string) => {
    setTodos(todos.map(todo =>
      todo.id === id ? { ...todo, completed: !todo.completed } : todo
    ))
  }

  const deleteTodo = (id: string) => {
    setTodos(todos.filter(todo => todo.id !== id))
  }

  const startEdit = (todo: Todo) => {
    setEditingId(todo.id)
    setEditTitle(todo.title)
  }

  const saveEdit = () => {
    if (!editingId) return
    setTodos(todos.map(todo =>
      todo.id === editingId ? { ...todo, title: editTitle } : todo
    ))
    setEditingId(null)
    setEditTitle('')
  }

  const clearCompleted = () => {
    setTodos(todos.filter(todo => !todo.completed))
  }

  const filteredTodos = todos.filter(todo => {
    if (filter.status === 'active' && todo.completed) return false
    if (filter.status === 'completed' && !todo.completed) return false
    if (filter.priority !== 'all' && todo.priority !== filter.priority) return false
    return true
  })

  return (
    <div className="todo-list">
      <h2>Todo List</h2>

      <div className="todo-input">
        <input
          type="text"
          value={newTodoTitle}
          onChange={(e) => setNewTodoTitle(e.target.value)}
          placeholder="Add a new todo..."
          onKeyPress={(e) => e.key === 'Enter' && addTodo()}
        />
        <button onClick={addTodo}>Add</button>
      </div>

      <div className="todo-filters">
        <div className="filter-group">
          <button onClick={() => setFilter({ ...filter, status: 'all' })}>
            All
          </button>
          <button onClick={() => setFilter({ ...filter, status: 'active' })}>
            Active
          </button>
          <button onClick={() => setFilter({ ...filter, status: 'completed' })}>
            Completed
          </button>
        </div>
        <select
          value={filter.priority}
          onChange={(e) => setFilter({ ...filter, priority: e.target.value as TodoFilter['priority'] })}
          aria-label="Priority filter"
        >
          <option value="all">All Priorities</option>
          <option value="high">High</option>
          <option value="medium">Medium</option>
          <option value="low">Low</option>
        </select>
      </div>

      <div className="todo-count">{filteredTodos.length} items</div>

      {filteredTodos.length === 0 ? (
        <p className="empty-state">No todos yet</p>
      ) : (
        <ul className="todo-items">
          {filteredTodos.map(todo => (
            <li key={todo.id} data-testid="todo-item" className={todo.completed ? 'completed' : ''}>
              {editingId === todo.id ? (
                <>
                  <input
                    value={editTitle}
                    onChange={(e) => setEditTitle(e.target.value)}
                  />
                  <button onClick={saveEdit} aria-label="Save">Save</button>
                </>
              ) : (
                <>
                  <input
                    type="checkbox"
                    checked={todo.completed}
                    onChange={() => toggleTodo(todo.id)}
                  />
                  <span className="todo-title">{todo.title}</span>
                  <button onClick={() => startEdit(todo)} aria-label="Edit">Edit</button>
                  <button onClick={() => deleteTodo(todo.id)} aria-label="Delete">Delete</button>
                </>
              )}
            </li>
          ))}
        </ul>
      )}

      <button onClick={clearCompleted} className="clear-completed">
