        self.cloud_client = CloudAPIBackend(self.config.get('cloud'))

    def _init_enterprise_client(self):
        """Initialize enterprise self-hosted client."""
        self.enterprise_client = EnterpriseBackend(self.config.get('enterprise'))

    async def complete(self, request: CompletionRequest) -> CompletionResult:
        """
        Generate code completion based on request parameters.
        Routes to appropriate backend based on mode and privacy requirements.
        """
        start_time = asyncio.get_event_loop().time()

        # Route based on mode
        if self.mode == CompletionMode.LOCAL:
            result = await self._local_complete(request)
        elif self.mode == CompletionMode.CLOUD:
            result = await self._cloud_complete(request)
        elif self.mode == CompletionMode.ENTERPRISE:
            result = await self._enterprise_complete(request)
        else:  # HYBRID
            result = await self._hybrid_complete(request)

        latency = (asyncio.get_event_loop().time() - start_time) * 1000
        result.latency_ms = latency

        return result

    async def _local_complete(self, request: CompletionRequest) -> CompletionResult:
        """Complete using local model."""
        # Privacy-preserving, no data leaves device
        return await self.local_model.complete(request)

