        """Complete using cloud API."""
        return await self.cloud_client.complete(request)

    async def _enterprise_complete(self, request: CompletionRequest) -> CompletionResult:
        """Complete using enterprise self-hosted model."""
        return await self.enterprise_client.complete(request)

    async def _hybrid_complete(self, request: CompletionRequest) -> CompletionResult:
        """
        Hybrid mode: Try local first for simple completions,
        fallback to cloud for complex requests.
