// Completion Provider Implementation
export class CompletionProvider implements vscode.InlineCompletionItemProvider {
    private securityManager: SecurityManager;
    private debounceTimer: NodeJS.Timeout | undefined;

    constructor(securityManager: SecurityManager) {
        this.securityManager = securityManager;
    }

    async provideInlineCompletionItems(
        document: vscode.TextDocument,
        position: vscode.Position,
        context: vscode.InlineCompletionContext,
        token: vscode.CancellationToken
    ): Promise<vscode.InlineCompletionItem[] | undefined> {

        // Debounce to avoid excessive API calls
        if (this.debounceTimer) {
            clearTimeout(this.debounceTimer);
        }

        return new Promise((resolve) => {
            this.debounceTimer = setTimeout(async () => {
                const completion = await this.fetchCompletion(document, position);
                resolve(completion ? [completion] : undefined);
            }, 50); // 50ms debounce
        });
    }

    private async fetchCompletion(
        document: vscode.TextDocument,
        position: vscode.Position
    ): Promise<vscode.InlineCompletionItem | undefined> {
        // Get context around cursor
        const range = new vscode.Range(
            new vscode.Position(Math.max(0, position.line - 50), 0),
            position
        );
        const context = document.getText(range);

        // Check privacy mode
        const mode = this.securityManager.getPrivacyMode();

        // Fetch completion based on mode
        const response = await fetch('http://localhost:8080/complete', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                code_context: context,
                language: document.languageId,
                file_path: document.fileName,
                mode: mode
            })
        });

        if (!response.ok) return undefined;

        const data = await response.json();
        return new vscode.InlineCompletionItem(
            data.text,
            new vscode.Range(position, position)
        );
    }
}
