Security and Privacy Module
Handles data protection, PII detection, and compliance.
"""

import re
from typing import List, Optional, Dict, Any
from dataclasses import dataclass
from enum import Enum

class PrivacyLevel(Enum):
    STRICT = "strict"      # No data leaves device
    BALANCED = "balanced"  # Anonymized data only
    PERMISSIVE = "permissive"  # Full cloud features

@dataclass
class PIIDetectionResult:
    has_pii: bool
    detected_types: List[str]
    sanitized_text: str
    risk_score: float

class PIIDetector:
    """Detects and sanitizes PII in code."""

    # Patterns for common PII
    PATTERNS = {
        'email': r'\\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Z|a-z]{2,}\\b',
        'phone': r'\\b\\d{3}[-.]?\\d{3}[-.]?\\d{4}\\b',
        'ssn': r'\\b\\d{3}-\\d{2}-\\d{4}\\b',
        'credit_card': r'\\b(?:\\d{4}[- ]?){3}\\d{4}\\b',
        'api_key': r'(?:api[_-]?key|apikey)[\\s]*[=:][\\s]*["\\']?[a-zA-Z0-9]{16,}["\\']?',
        'password': r'(?:password|passwd|pwd)[\\s]*[=:][\\s]*["\\'][^"\\']{4,}["\\']',
        'ip_address': r'\\b(?:\\d{1,3}\\.){3}\\d{1,3}\\b',
        'aws_key': r'AKIA[0-9A-Z]{16}',
        'private_key': r'-----BEGIN (?:RSA |DSA |EC )?PRIVATE KEY-----',
    }

    def __init__(self):
        self.compiled_patterns = {
            name: re.compile(pattern, re.IGNORECASE)
            for name, pattern in self.PATTERNS.items()
        }

    def detect(self, text: str) -> PIIDetectionResult:
        """Detect PII in text."""
        detected_types = []
        sanitized = text
        total_matches = 0

        for pii_type, pattern in self.compiled_patterns.items():
            matches = pattern.findall(text)
            if matches:
                detected_types.append(pii_type)
                total_matches += len(matches)
                # Replace with placeholder
                sanitized = pattern.sub(f'[{pii_type.upper()}_REDACTED]', sanitized)

        risk_score = min(1.0, total_matches * 0.1)

        return PIIDetectionResult(
            has_pii=len(detected_types) > 0,
            detected_types=detected_types,
            sanitized_text=sanitized,
            risk_score=risk_score
        )

class SecurityManager:
    """Manages security settings and privacy controls."""

    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}
        self.pii_detector = PIIDetector()
        self._privacy_mode = PrivacyLevel.BALANCED
        self._enterprise_mode = self.config.get('enterprise_mode', False)
        self._approved_domains = self.config.get('approved_domains', [])

    @property
    def privacy_mode(self) -> PrivacyLevel:
        return self._privacy_mode

    def set_privacy_mode(self, mode: PrivacyLevel):
        """Set privacy mode."""
        self._privacy_mode = mode

    def process_request(self, request: Dict[str, Any]) -> Dict[str, Any]:
        """
        Process outgoing request to ensure privacy compliance.
        Returns sanitized request.
        """
        # Check for PII in code context
        if 'code_context' in request:
            pii_result = self.pii_detector.detect(request['code_context'])

            if self._privacy_mode == PrivacyLevel.STRICT:
                # In strict mode, block if PII detected
                if pii_result.has_pii:
                    raise SecurityError(
                        f"PII detected: {', '.join(pii_result.detected_types)}. "
                        "Strict mode prevents sending sensitive data."
                    )

            elif self._privacy_mode == PrivacyLevel.BALANCED:
                # Sanitize and proceed
                request['code_context'] = pii_result.sanitized_text
                request['was_sanitized'] = pii_result.has_pii

        # Add enterprise headers if needed
        if self._enterprise_mode:
            request['headers'] = request.get('headers', {})
            request['headers']['X-Enterprise-Context'] = 'true'

        return request

    def verify_response(self, response: Dict[str, Any]) -> bool:
        """Verify incoming response for security issues."""
        # Check for suspicious content
        if 'text' in response:
            # Simple check for obvious attacks
            suspicious = [
                'rm -rf /',
                'format C:',
                'dd if=/dev/zero',
                '>:(){:|:&};:'
            ]
            for pattern in suspicious:
                if pattern in response['text'].lower():
                    return False
        return True

