<parameter name="content">const { generateId, formatDate } = require('../utils/helpers');
const db = require('./database');

const VALID_STATUSES = ['pending', 'in_progress', 'completed', 'cancelled'];
const VALID_PRIORITIES = ['low', 'medium', 'high', 'urgent'];

class Task {
  static findAll(queries = {}, userId = null) {
    let tasks = [...db.tasks];

    // Filter by user (if not admin)
    if (userId) {
      tasks = tasks.filter(t => t.user_id === userId);
    }

    // Filter by status
    if (queries.status) {
      const statuses = queries.status.split(',');
      tasks = tasks.filter(t => statuses.includes(t.status));
    }

    // Filter by priority
    if (queries.priority) {
      const priorities = queries.priority.split(',');
      tasks = tasks.filter(t => priorities.includes(t.priority));
    }

    // Search by title or description
    if (queries.q) {
      const q = queries.q.toLowerCase();
      tasks = tasks.filter(t => 
        t.title.toLowerCase().includes(q) || 
        t.description.toLowerCase().includes(q)
      );
    }

    // Sorting
    if (queries.sort) {
      const sortField = queries.sort.replace(/^-/, '');
      const sortOrder = queries.sort.startsWith('-') ? -1 : 1;
      tasks.sort((a, b) => {
        if (a[sortField] < b[sortField]) return -1 * sortOrder;
        if (a[sortField] > b[sortField]) return 1 * sortOrder;
        return 0;
      });
    } else {
      // Default sort by created_at desc
      tasks.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
    }

    return tasks;
  }

  static findById(id) {
    return db.tasks.find(t => t.id === id) || null;
  }

  static create(taskData, userId) {
    const task = {
      id: generateId(),
      title: taskData.title,
      description: taskData.description || '',
      status: taskData.status || 'pending',
      priority: taskData.priority || 'medium',
      user_id: userId,
      created_at: formatDate(),
      updated_at: formatDate()
    };

    db.tasks.push(task);
    return task;
  }

  static update(id, updates) {
    const index = db.tasks.findIndex(t => t.id === id);
    if (index === -1) return null;

    const task = db.tasks[index];

    db.tasks[index] = {
      ...task,
      ...updates,
      updated_at: formatDate()
    };

    return db.tasks[index];
  }

  static delete(id) {
    const index = db.tasks.findIndex(t => t.id === id);
    if (index === -1) return false;

    db.tasks.splice(index, 1);
    return true;
  }

  static isValidStatus(status) {
    return VALID_STATUSES.includes(status);
  }

  static isValidPriority(priority) {
    return VALID_PRIORITIES.includes(priority);
  }
}

module.exports = Task;
