<parameter name="content">const Joi = require('joi');

const schemas = {
  // Authentication
  register: Joi.object({
    email: Joi.string().email().required(),
    password: Joi.string().min(8).pattern(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/).required()
      .messages({
        'string.pattern.base': 'Password must contain at least one uppercase letter, one lowercase letter, and one number'
      }),
    name: Joi.string().min(2).max(100).required()
  }),

  login: Joi.object({
    email: Joi.string().email().required(),
    password: Joi.string().required()
  }),

  // User updates
  updateUser: Joi.object({
    name: Joi.string().min(2).max(100),
    email: Joi.string().email()
  }).min(1),

  // Tasks
  createTask: Joi.object({
    title: Joi.string().min(1).max(200).required(),
    description: Joi.string().max(2000),
    status: Joi.string().valid('pending', 'in_progress', 'completed', 'cancelled'),
    priority: Joi.string().valid('low', 'medium', 'high', 'urgent')
  }),

  updateTask: Joi.object({
    title: Joi.string().min(1).max(200),
    description: Joi.string().max(2000),
    status: Joi.string().valid('pending', 'in_progress', 'completed', 'cancelled'),
    priority: Joi.string().valid('low', 'medium', 'high', 'urgent')
  }).min(1),

  // Pagination
  pagination: Joi.object({
    page: Joi.number().integer().min(1).default(1),
    per_page: Joi.number().integer().min(1).max(100).default(20)
  })
};

const validateRequest = (schemaName) => {
  return (req, res, next) => {
    const schema = schemas[schemaName];
    if (!schema) {
      return next();
    }

    const { error, value } = schema.validate(req.body || req.query, {
      abortEarly: false,
      stripUnknown: true
    });

    if (error) {
      return next(error);
    }

    // Replace with validated/cleaned data
    if (req.body) req.body = value;
    if (req.query) req.query = value;

    next();
  };
};

module.exports = { validateRequest, schemas };
</parameter>
</invoke>
