<parameter name="content">const express = require('express');
const jwt = require('jsonwebtoken');
const User = require('../models/User');
const { validateRequest } = require('../middleware/validateRequest');
const { authenticate } = require('../middleware/authenticate');
const { sanitizeUser } = require('../utils/helpers');
const { UnauthorizedError } = require('../utils/errors');
const config = require('../config');

const router = express.Router();

// POST /api/v1/auth/register
router.post('/register', validateRequest('register'), async (req, res, next) => {
  try {
    // Check if user exists
    const existingUser = User.findByEmail(req.body.email);
    if (existingUser) {
      return res.status(409).json({
        error: {
          code: 'EMAIL_EXISTS',
          message: 'An account with this email already exists'
        }
      });
    }

    // Create user
    const user = await User.create(req.body);

    // Generate token
    const token = jwt.sign(
      { sub: user.id, email: user.email, role: user.role },
      config.jwt.secret,
      { expiresIn: config.jwt.expiresIn }
    );

    res.status(201).json({
      data: {
        user: sanitizeUser(user),
        token
      }
    });
  } catch (err) {
    next(err);
  }
});

// POST /api/v1/auth/login
router.post('/login', validateRequest('login'), async (req, res, next) => {
  try {
    const { email, password } = req.body;

    // Find user
    const user = User.findByEmail(email);
    if (!user) {
      throw new UnauthorizedError('Invalid credentials');
    }

    // Validate password
    const isValidPassword = await User.validatePassword(user, password);
    if (!isValidPassword) {
      throw new UnauthorizedError('Invalid credentials');
    }

    // Generate token
    const token = jwt.sign(
      { sub: user.id, email: user.email, role: user.role },
      config.jwt.secret,
      { expiresIn: config.jwt.expiresIn }
    );

    res.json({
      data: {
        user: sanitizeUser(user),
        token
      }
    });
  } catch (err) {
    next(err);
  }
});

// GET /api/v1/auth/me
router.get('/me', authenticate, (req, res) => {
  res.json({
    data: sanitizeUser(req.user)
  });
});

module.exports = router;
</parameter>
</invoke>
