<parameter name="content">const express = require('express');
const User = require('../models/User');
const { authenticate } = require('../middleware/authenticate');
const { validateRequest } = require('../middleware/validateRequest');
const { createPaginatedResponse, sanitizeUser } = require('../utils/helpers');
const { NotFoundError } = require('../utils/errors');

const router = express.Router();

// All user routes require authentication
router.use(authenticate);

// GET /api/v1/users
router.get('/', (req, res) => {
  const page = parseInt(req.query.page) || 1;
  const perPage = parseInt(req.query.per_page) || 20;

  let users = User.findAll(req.query);
  const total = users.length;

  // Paginate
  const startIndex = (page - 1) * perPage;
  const endIndex = startIndex + perPage;
  users = users.slice(startIndex, endIndex).map(sanitizeUser);

  res.json(createPaginatedResponse(users, page, perPage, total));
});

// GET /api/v1/users/me
router.get('/me', (req, res) => {
  res.json({
    data: sanitizeUser(req.user)
  });
});

// PATCH /api/v1/users/me
router.patch('/me', validateRequest('updateUser'), async (req, res, next) => {
  try {
    const user = await User.update(req.user.id, req.body);
    res.json({
      data: sanitizeUser(user)
    });
  } catch (err) {
    next(err);
  }
});

// DELETE /api/v1/users/me
router.delete('/me', async (req, res, next) => {
  try {
    User.delete(req.user.id);
    res.status(204).send();
  } catch (err) {
    next(err);
  }
});

// GET /api/v1/users/:id
router.get('/:id', (req, res, next) => {
  const user = User.findById(req.params.id);

  if (!user) {
    return next(new NotFoundError('User'));
  }

  res.json({
    data: sanitizeUser(user)
  });
});

module.exports = router;
</parameter>
