<parameter name="content">const express = require('express');
const Task = require('../models/Task');
const { authenticate } = require('../middleware/authenticate');
const { validateRequest } = require('../middleware/validateRequest');
const { createPaginatedResponse } = require('../utils/helpers');
const { NotFoundError, ForbiddenError } = require('../utils/errors');

const router = express.Router();

// All task routes require authentication
router.use(authenticate);

// GET /api/v1/tasks
router.get('/', (req, res) => {
  const page = parseInt(req.query.page) || 1;
  const perPage = parseInt(req.query.per_page) || 20;

  // Users can only see their own tasks (unless admin)
  const userId = req.user.role === 'admin' ? null : req.user.id;

  let tasks = Task.findAll(req.query, userId);
  const total = tasks.length;

  // Paginate
  const startIndex = (page - 1) * perPage;
  const endIndex = startIndex + perPage;
  tasks = tasks.slice(startIndex, endIndex);

  res.json(createPaginatedResponse(tasks, page, perPage, total));
});

// GET /api/v1/tasks/:id
router.get('/:id', (req, res, next) => {
  const task = Task.findById(req.params.id);

  if (!task) {
    return next(new NotFoundError('Task'));
  }

  // Users can only access their own tasks
  if (req.user.role !== 'admin' && task.user_id !== req.user.id) {
    return next(new ForbiddenError('You do not have access to this task'));
  }

  res.json({
    data: task
  });
});

// POST /api/v1/tasks
router.post('/', validateRequest('createTask'), (req, res, next) => {
  try {
    const task = Task.create(req.body, req.user.id);

    res.status(201).json({
      data: task
    });
  } catch (err) {
    next(err);
  }
});

// PATCH /api/v1/tasks/:id
router.patch('/:id', validateRequest('updateTask'), (req, res, next) => {
  const task = Task.findById(req.params.id);

  if (!task) {
    return next(new NotFoundError('Task'));
  }

  // Users can only update their own tasks
  if (req.user.role !== 'admin' && task.user_id !== req.user.id) {
    return next(new ForbiddenError('You do not have access to this task'));
  }

  const updatedTask = Task.update(req.params.id, req.body);

  res.json({
    data: updatedTask
  });
});

// DELETE /api/v1/tasks/:id
router.delete('/:id', (req, res, next) => {
  const task = Task.findById(req.params.id);

  if (!task) {
    return next(new NotFoundError('Task'));
  }

  // Users can only delete their own tasks
  if (req.user.role !== 'admin' && task.user_id !== req.user.id) {
    return next(new ForbiddenError('You do not have access to this task'));
  }

  Task.delete(req.params.id);

  res.status(204).send();
});

module.exports = router;
</parameter>
