"""
TASK 1: Code Quality Analysis
Analyzes code quality issues in the legacy codebase
"""
import os
import re
import json
from pathlib import Path

class CodeQualityAnalyzer:
    def __init__(self, base_path):
        self.base_path = Path(base_path)
        self.issues = []
        self.metrics = {
            'total_files': 0,
            'total_lines': 0,
            'python_files': 0,
            'issues_found': 0
        }

    def analyze(self):
        """Run all analysis checks"""
        for root, dirs, files in os.walk(self.base_path):
            for file in files:
                file_path = Path(root) / file
                if file.endswith('.py'):
                    self.analyze_python_file(file_path)
                elif file == 'requirements.txt':
                    self.analyze_dependencies(file_path)

        return self.generate_report()

    def analyze_python_file(self, file_path):
        """Analyze a single Python file"""
        try:
            with open(file_path, 'r', encoding='utf-8') as f:
                content = f.read()
                lines = content.split('\n')

                self.metrics['python_files'] += 1
                self.metrics['total_files'] += 1
                self.metrics['total_lines'] += len(lines)

                # Check for issues
                self.check_bare_excepts(content, file_path)
                self.check_sql_injection(content, file_path)
                self.check_bare_comparisons(content, file_path)
                self.check_global_variables(content, file_path)
                self.check_code_duplication(content, file_path)
                self.check_deprecated_libraries(content, file_path)
                self.check_security_issues(content, file_path)
                self.check_resource_management(content, file_path)
        except Exception as e:
            print(f"Error analyzing {file_path}: {e}")

    def check_bare_excepts(self, content, file_path):
        if re.search(r'except\s*:', content):
            self.issues.append({
                'file': str(file_path),
                'severity': 'HIGH',
                'category': 'Error Handling',
                'issue': 'Bare except clause (captures all exceptions including SystemExit)',
                'recommendation': 'Use specific exceptions: except ValueError:'
            })
            self.metrics['issues_found'] += 1

    def check_sql_injection(self, content, file_path):
        f_string_patterns = re.findall(r'f["\'][^"\']*SELECT[^}]*\{[^}]+\}', content, re.IGNORECASE)
        for pattern in f_string_patterns:
            self.issues.append({
                'file': str(file_path),
                'severity': 'CRITICAL',
                'category': 'Security',
                'issue': 'SQL Injection vulnerability - f-string in SQL query',
                'recommendation': 'Use parameterized queries: cursor.execute("SELECT * FROM users WHERE id = ?", (user_id,))'
            })
            self.metrics['issues_found'] += 1

    def check_bare_comparisons(self, content, file_path):
        # Check for == True or == False
        for line_num, line in enumerate(content.split('\n'), 1):
            if re.search(r'==\s*True|==\s*False|!=\s*None', line):
                self.issues.append({
                    'file': str(file_path),
                    'severity': 'MEDIUM',
                    'category': 'Style',
                    'issue': 'Redundant comparison with True/False/None',
                    'recommendation': 'Use "if user[active]:" instead of "if user[active] == True:"'
                })
                self.metrics['issues_found'] += 1

    def check_global_variables(self, content, file_path):
        global_vars = re.findall(r'^(\w+)\s*=\s*[^=]', content, re.MULTILINE)
        if len(global_vars) > 2:
            self.issues.append({
                'file': str(file_path),
                'severity': 'MEDIUM',
                'category': 'Maintainability',
                'issue': f'Multiple global variables ({len(global_vars)})',
                'recommendation': 'Encapsulate state in classes or use dependency injection'
            })
            self.metrics['issues_found'] += 1

    def check_code_duplication(self, content, file_path):
        # Check for similar function patterns
        functions = re.findall(r'def\s+(\w+)\s*\([^)]*\)[^:]*:', content)
        similar_names = [f for f in functions if re.search(r'v\d|_\d|_version', f)]
        for name in similar_names:
            self.issues.append({
                'file': str(file_path),
                'severity': 'LOW',
                'category': 'Maintainability',
                'issue': f'Potentially duplicated code: function "{name}"',
                'recommendation': 'Consolidate similar functions and use parameters'
            })
            self.metrics['issues_found'] += 1

    def check_deprecated_libraries(self, content, file_path):
        if 'hashlib.md5' in content:
            self.issues.append({
                'file': str(file_path),
                'severity': 'CRITICAL',
                'category': 'Security',
                'issue': 'Using MD5 for password hashing - cryptographically broken',
                'recommendation': 'Use bcrypt, argon2, or scrypt for password hashing'
            })
            self.metrics['issues_found'] += 1

    def check_security_issues(self, content, file_path):
        if 'password' in content.lower() and '=\s*[\"\']' in content:
            if re.search(r'password\s*=\s*["\'][^"\']+["\']', content, re.IGNORECASE):
                self.issues.append({
                    'file': str(file_path),
                    'severity': 'CRITICAL',
                    'category': 'Security',
                    'issue': 'Hardcoded password or secret in code',
                    'recommendation': 'Use environment variables or secrets manager'
                })
                self.metrics['issues_found'] += 1

    def check_resource_management(self, content, file_path):
        if '.close()' in content and 'with ' not in content:
            self.issues.append({
                'file': str(file_path),
                'severity': 'MEDIUM',
                'category': 'Reliability',
                'issue': 'Resource not using context manager (with statement)',
                'recommendation': 'Use "with sqlite3.connect(...) as conn:" for proper resource management'
            })
            self.metrics['issues_found'] += 1

    def analyze_dependencies(self, file_path):
        try:
            with open(file_path, 'r') as f:
                content = f.read()
                # Check for outdated Flask
                if 'flask==0.12' in content.lower():
                    self.issues.append({
                        'file': str(file_path),
                        'severity': 'CRITICAL',
                        'category': 'Dependencies',
                        'issue': 'Flask 0.12.x has known security vulnerabilities (CVE-2018-1000656)',
                        'recommendation': 'Upgrade to Flask 2.3+ or migrate to FastAPI'
                    })
                    self.metrics['issues_found'] += 1
                # Check old requests
                if 'requests==2.20' in content:
                    self.issues.append({
                        'file': str(file_path),
                        'severity': 'HIGH',
                        'category': 'Dependencies',
                        'issue': 'Requests 2.20 is outdated (2018)',
                        'recommendation': 'Upgrade to requests 2.31+'
                    })
                    self.metrics['issues_found'] += 1
        except Exception as e:
            print(f"Error analyzing deps {file_path}: {e}")

    def generate_report(self):
        severity_count = {}
        category_count = {}
        for issue in self.issues:
            severity_count[issue['severity']] = severity_count.get(issue['severity'], 0) + 1
            category_count[issue['category']] = category_count.get(issue['category'], 0) + 1

        # Calculate overall quality score
        base_score = 100
        deductions = {
            'CRITICAL': 15,
            'HIGH': 10,
            'MEDIUM': 5,
            'LOW': 2
        }
        for issue in self.issues:
            base_score -= deductions.get(issue['severity'], 1)
        score = max(0, base_score)

        report = {
            'timestamp': '2024-03-28',
            'summary': self.metrics,
            'quality_score': score,
            'severity_breakdown': severity_count,
            'category_breakdown': category_count,
            'issues': self.issues,
            'recommendations': self.get_recommendations()
        }

        # Save to file
        with open('code_quality_report.json', 'w') as f:
            json.dump(report, f, indent=2)

        return report

    def get_recommendations(self):
        return [
            "1. IMMEDIATE: Fix SQL injection vulnerabilities in database queries",
            "2. IMMEDIATE: Replace MD5 password hashing with bcrypt or argon2",
            "3. IMMEDIATE: Upgrade Flask from 0.12.5 to 2.3+",
            "4. HIGH: Replace bare except clauses with specific exception handling",
            "5. HIGH: Use context managers (with statements) for resource management",
            "6. MEDIUM: Implement environment variables for configuration",
            "7. MEDIUM: Add type hints and input validation",
            "8. LOW: Consolidate duplicate code patterns"
        ]

# Execute analysis
print("=" * 60)
print("TASK 1: CODE QUALITY ANALYSIS")
print("=" * 60)
analyzer = CodeQualityAnalyzer('.')
report = analyzer.analyze()

print(f"\n📊 QUALITY SCORE: {report['quality_score']}/100")
print(f"\n📁 Files Analyzed: {report['summary']['total_files']}")
print(f"🐍 Python Files: {report['summary']['python_files']}")
print(f"📏 Total Lines: {report['summary']['total_lines']}")
print(f"❌ Issues Found: {report['summary']['issues_found']}\n")

print("Severity Breakdown:")
for sev, count in report['severity_breakdown'].items():
    print(f"  {sev}: {count}")

print("\nTop Priority Issues:")
critical_high = [i for i in report['issues'] if i['severity'] in ['CRITICAL', 'HIGH']][:5]
