"""Business logic services."""
from typing import List, Optional, Dict
from models import User, UserCreate, Item, ItemCreate
from datetime import datetime
import hashlib
import secrets

class UserService:
    """User management service."""
    _users: Dict[int, User] = {}
    _id_counter: int = 1

    @classmethod
    def create(cls, user_data: UserCreate) -> User:
        user_id = cls._id_counter
        cls._id_counter += 1

        user = User(
            id=user_id,
            username=user_data.username,
            email=user_data.email,
            full_name=user_data.full_name,
            role=user_data.role,
            is_active=user_data.is_active,
            created_at=datetime.utcnow()
        )
        cls._users[user_id] = user
        return user

    @classmethod
    def get_by_id(cls, user_id: int) -> Optional[User]:
        return cls._users.get(user_id)

    @classmethod
    def get_all(cls) -> List[User]:
        return list(cls._users.values())

    @classmethod
    def update(cls, user_id: int, updates: dict) -> Optional[User]:
        if user_id not in cls._users:
            return None
        user = cls._users[user_id]
        for key, value in updates.items():
            if hasattr(user, key) and key != 'id':
                setattr(user, key, value)
        user.updated_at = datetime.utcnow()
        return user

    @classmethod
    def delete(cls, user_id: int) -> bool:
        if user_id in cls._users:
            del cls._users[user_id]
            return True
        return False

class ItemService:
    """Item management service."""
    _items: Dict[int, Item] = {}
    _id_counter: int = 1

    @classmethod
    def create(cls, item_data: ItemCreate, owner_id: int) -> Item:
        item_id = cls._id_counter
        cls._id_counter += 1

        item = Item(
            id=item_id,
            title=item_data.title,
            description=item_data.description,
            price=item_data.price,
            is_available=item_data.is_available,
            owner_id=owner_id,
            created_at=datetime.utcnow()
        )
        cls._items[item_id] = item
        return item

    @classmethod
    def get_by_id(cls, item_id: int) -> Optional[Item]:
        return cls._items.get(item_id)

    @classmethod
    def get_all(cls, skip: int = 0, limit: int = 100) -> List[Item]:
        items = list(cls._items.values())
        return items[skip:skip + limit]

    @classmethod
    def get_by_owner(cls, owner_id: int) -> List[Item]:
        return [item for item in cls._items.values() if item.owner_id == owner_id]

    @classmethod
    def delete(cls, item_id: int) -> bool:
        if item_id in cls._items:
            del cls._items[item_id]
            return True
        return False

class AuthService:
    """Authentication service."""
    _tokens: Dict[str, int] = {}

    @classmethod
    def hash_password(cls, password: str) -> str:
        salt = secrets.token_hex(16)
        return hashlib.sha256(f"{password}{salt}".encode()).hexdigest()

    @classmethod
    def create_token(cls, user_id: int) -> str:
        token = secrets.token_urlsafe(32)
        cls._tokens[token] = user_id
        return token

    @classmethod
    def verify_token(cls, token: str) -> Optional[int]:
        return cls._tokens.get(token)
