import requests
import json
import os
import logging

# Configuration
API_URL = "https://api.example.com"
OUTPUT_DIR = "./output"

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def fetch_users():
    """Fetch users from API."""
    logger.info("Fetching users...")
    try:
        response = requests.get(f"{API_URL}/users", timeout=10)
        if response.status_code == 200:
            users = response.json()
            if not os.path.exists(OUTPUT_DIR):
                os.makedirs(OUTPUT_DIR)
            with open(f"{OUTPUT_DIR}/users.json", "w") as f:
                json.dump(users, f, indent=2)
            logger.info(f"Users saved: {len(users)} users")
            return users
        else:
            logger.error(f"Failed to fetch users: {response.status_code}")
            return []
    except Exception as e:
        logger.error(f"Error fetching users: {e}")
        return []

def fetch_products():
    """Fetch products from API."""
    logger.info("Fetching products...")
    try:
        response = requests.get(f"{API_URL}/products", timeout=10)
        if response.status_code == 200:
            products = response.json()
            if not os.path.exists(OUTPUT_DIR):
                os.makedirs(OUTPUT_DIR)
            with open(f"{OUTPUT_DIR}/products.json", "w") as f:
                json.dump(products, f, indent=2)
            logger.info(f"Products saved: {len(products)} products")
            return products
        else:
            logger.error(f"Failed to fetch products: {response.status_code}")
            return []
    except Exception as e:
        logger.error(f"Error fetching products: {e}")
        return []

def fetch_orders():
    """Fetch orders from API."""
    logger.info("Fetching orders...")
    try:
        response = requests.get(f"{API_URL}/orders", timeout=10)
        if response.status_code == 200:
            orders = response.json()
            if not os.path.exists(OUTPUT_DIR):
                os.makedirs(OUTPUT_DIR)
            with open(f"{OUTPUT_DIR}/orders.json", "w") as f:
                json.dump(orders, f, indent=2)
            logger.info(f"Orders saved: {len(orders)} orders")
            return orders
        else:
            logger.error(f"Failed to fetch orders: {response.status_code}")
            return []
    except Exception as e:
        logger.error(f"Error fetching orders: {e}")
        return []

def process_name(name):
    """Process a name: capitalize and trim."""
    if name:
        result = ""
        for char in name.strip():
            if char.isalpha() or char == " ":
                result += char.lower()
        return result.capitalize()
    return ""

def process_email(email):
    """Process an email: lowercase and trim."""
    if email:
        result = ""
        for char in email.strip():
            if char.isalnum() or char in "@._-":
                result += char.lower()
        return result
    return ""

def main():
