import numpy as np
import time
from collections import OrderedDict, defaultdict
import random

np.random.seed(42)
random.seed(42)

class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = OrderedDict()
        self.hits = 0
        self.misses = 0
    def get(self, key):
        if key in self.cache:
            self.cache.move_to_end(key)
            self.hits += 1
            return self.cache[key]
        self.misses += 1
        return None
    def put(self, key, value):
        if key in self.cache:
            self.cache.move_to_end(key)
        else:
            if len(self.cache) >= self.capacity:
                self.cache.popitem(last=False)
        self.cache[key] = value
    def hit_rate(self):
        total = self.hits + self.misses
        return self.hits / total if total > 0 else 0

class LFUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.key_to_val = {}
        self.key_to_freq = {}
        self.freq_to_keys = defaultdict(set)
        self.min_freq = 0
        self.hits = 0
        self.misses = 0
    def get(self, key):
        if key not in self.key_to_val:
            self.misses += 1
            return None
        self._update_freq(key)
        self.hits += 1
        return self.key_to_val[key]
    def put(self, key, value):
        if self.capacity <= 0:
            return
        if key in self.key_to_val:
            self.key_to_val[key] = value
            self._update_freq(key)
        else:
            if len(self.key_to_val) >= self.capacity:
                self._evict()
            self.key_to_val[key] = value
            self.key_to_freq[key] = 1
            self.freq_to_keys[1].add(key)
            self.min_freq = 1
    def _update_freq(self, key):
        freq = self.key_to_freq[key]
        self.freq_to_keys[freq].remove(key)
        if not self.freq_to_keys[freq]:
            del self.freq_to_keys[freq]
            if self.min_freq == freq:
                self.min_freq += 1
        self.key_to_freq[key] = freq + 1
        self.freq_to_keys[freq + 1].add(key)
    def _evict(self):
        key = next(iter(self.freq_to_keys[self.min_freq]))
        self.freq_to_keys[self.min_freq].remove(key)
        if not self.freq_to_keys[self.min_freq]:
            del self.freq_to_keys[self.min_freq]
        del self.key_to_val[key]
        del self.key_to_freq[key]
    def hit_rate(self):
        total = self.hits + self.misses
        return self.hits / total if total > 0 else 0

def zipfian(n_items, n_accesses, alpha=1.0):
    probs = np.array([1.0 / (i ** alpha) for i in range(1, n_items + 1)])
    probs /= probs.sum()
    return np.random.choice(n_items, size=n_accesses, p=probs).tolist()

def benchmark(cache_class, workload, cache_size, runs=3):
    times = []
    for _ in range(runs):
        cache = cache_class(cache_size)
        start = time.perf_counter()
        for key in workload:
            if cache.get(key) is None:
                cache.put(key, True)
        times.append(time.perf_counter() - start)
    return cache.hit_rate(), min(times)

