export interface CounterState {
  count: number
  min: number
  max: number
}

export class Counter {
  private state: CounterState

  constructor(initial = 0, min = -Infinity, max = Infinity) {
    this.state = { count: initial, min, max }
  }

  increment(amount = 1): number {
    const newCount = this.state.count + amount
    if (newCount > this.state.max) {
      throw new Error(`Count cannot exceed ${this.state.max}`)
    }
    this.state.count = newCount
    return this.state.count
  }

  decrement(amount = 1): number {
    const newCount = this.state.count - amount
    if (newCount < this.state.min) {
      throw new Error(`Count cannot be less than ${this.state.min}`)
    }
    this.state.count = newCount
    return this.state.count
  }

  getCount(): number {
    return this.state.count
  }

  reset(value = 0): void {
    this.state.count = value
  }
}

export function formatCurrency(amount: number, currency = "USD"): string {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency,
  }).format(amount)
}

export function truncate(str: string, maxLength: number): string {
  if (str.length <= maxLength) return str
  return str.slice(0, maxLength - 3) + "..."
}

export function debounce<T extends (...args: any[]) => any>(
  fn: T,
  delay: number
): (...args: Parameters<T>) => void {
  let timeoutId: ReturnType<typeof setTimeout>
  return (...args: Parameters<T>) => {
    clearTimeout(timeoutId)
    timeoutId = setTimeout(() => fn(...args), delay)
  }
}
