const fs = require('fs');
const path = require('path');

// Task 1: Code Quality Analysis
const results = {
  task: "Code Quality Analysis",
  timestamp: new Date().toISOString(),
  summary: {
    filesAnalyzed: 3,
    totalIssues: 0,
    categories: {}
  },
  files: [],
  recommendations: []
};

const issuesCatalog = [];
const jsFiles = ['oldsystem.js', 'api.js', 'server.js'];

jsFiles.forEach(file => {
  const content = fs.readFileSync(file, 'utf8');
  const lines = content.split('\n');
  const fileIssues = [];

  // Rule 1: Check for var usage (should use let/const)
  const varMatches = content.match(/var\s+/g);
  if (varMatches) {
    const count = varMatches.length;
    fileIssues.push({ rule: 'ES6_variables', severity: 'medium', count, message: `Found ${count} 'var' declarations` });
  }

  // Rule 2: Check for hardcoded credentials
  if (/password.*=.*['"][^'"]+['"]/.test(content)) {
    fileIssues.push({ rule: 'security_hardcoded_secrets', severity: 'critical', message: 'Hardcoded password detected' });
  }

  // Rule 3: SQL Injection risk
  if (/query.*\+/.test(content) || /query.*\$\{/.test(content)) {
    fileIssues.push({ rule: 'security_sql_injection', severity: 'critical', message: 'Potential SQL injection vulnerability' });
  }

  // Rule 4: Callback hell
  const nestedCallbacks = (content.match(/function\s*\([^)]*\)\s*\{/g) || []).length;
  if (nestedCallbacks > 2) {
    fileIssues.push({ rule: 'maintainability_callbacks', severity: 'medium', count: nestedCallbacks, message: 'Multiple nested callbacks detected' });
  }

  // Rule 5: No error handling
  if (!/try\s*\{|catch\s*\(/.test(content) && /query|connect/.test(content)) {
    fileIssues.push({ rule: 'error_handling', severity: 'high', message: 'Missing try-catch in database operations' });
  }

  // Rule 6: Function complexity
  const functions = content.match(/function\s+\w+\s*\([^)]*\)\s*\{/g) || [];
  functions.forEach(fn => {
    fileIssues.push({ rule: 'function_complexity', severity: 'low', message: `Legacy function style: ${fn.slice(0, 30)}...` });
  });

  issuesCatalog.push({ file, issues: fileIssues, linesOfCode: lines.length });
});

// Calculate summary
issuesCatalog.forEach(f => {
  results.summary.totalIssues += f.issues.length;
  f.issues.forEach(issue => {
    results.summary.categories[issue.rule] = (results.summary.categories[issue.rule] || 0) + 1;
  });
  results.files.push({ name: f.file, linesOfCode: f.linesOfCode, issues: f.issues });
});

// Generate recommendations
if (results.summary.categories['security_hardcoded_secrets']) {
  results.recommendations.push('IMMEDIATE: Move hardcoded credentials to environment variables');
}
if (results.summary.categories['security_sql_injection']) {
  results.recommendations.push('URGENT: Use parameterized queries to prevent SQL injection');
}
if (results.summary.categories['ES6_variables']) {
  results.recommendations.push('Refactor to ES6+ let/const declarations');
}
if (results.summary.categories['maintainability_callbacks']) {
  results.recommendations.push('Convert callbacks to async/await or Promises');
}
results.recommendations.push('Add comprehensive error handling middleware');

fs.writeFileSync('analysis_results/1_code_quality.json', JSON.stringify(results, null, 2));
console.log('✅ Task 1 Complete - Code Quality Analysis saved to analysis_results/1_code_quality.json');
