#!/usr/bin/env python3
"""Task 1: Code Quality Analysis"""

import ast
import sys
from pathlib import Path

REPORT_FILE = "/root/delegation-demo/report_code_quality.md"

def analyze_file(filepath):
    """Analyze Python file for quality issues"""
    with open(filepath, 'r') as f:
        content = f.read()
        tree = ast.parse(content)

    issues = []
    metrics = {
        'lines_of_code': len(content.splitlines()),
        'functions': 0,
        'classes': 0,
        'imports': 0
    }

    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef):
            metrics['functions'] += 1
        elif isinstance(node, ast.ClassDef):
            metrics['classes'] += 1
        elif isinstance(node, ast.Import) or isinstance(node, ast.ImportFrom):
            metrics['imports'] += 1
        elif isinstance(node, ast.Call):
            # Check for SQL injection risks (f-strings in SQL)
            if hasattr(node.func, 'attr') and node.func.attr == 'execute':
                for arg in node.args:
                    if isinstance(arg, ast.JoinedStr):
                        issues.append({
                            'line': node.lineno,
                            'severity': 'CRITICAL',
                            'issue': 'SQL Injection Risk - f-string used in SQL query',
                            'fix': 'Use parameterized queries with placeholders'
                        })

    # Pattern-based analysis
    lines = content.splitlines()
    for i, line in enumerate(lines, 1):
        if 'password' in line.lower() and '=' in line:
            if "'" in line or '"' in line:
                if 'hash' not in line.lower() and 'encrypt' not in line.lower():
                    issues.append({
                        'line': i,
                        'severity': 'HIGH',
                        'issue': 'Potential plaintext password handling',
                        'fix': 'Use proper password hashing (bcrypt, argon2)'
                    })

        if 'hardcoded' in line.lower() or (i > 0 and 'config' in line.lower() and '=' in line):
            issues.append({
                'line': i,
                'severity': 'MEDIUM',
                'issue': 'Potential hardcoded configuration',
                'fix': 'Move configuration to environment variables or config files'
            })

    return metrics, issues

def main():
    filepath = "/root/delegation-demo/sample_legacy_app.py"
    metrics, issues = analyze_file(filepath)

    report = f"""# 🔍 Code Quality Analysis Report

## Overview
| Metric | Value |
|--------|-------|
| Lines of Code | {metrics['lines_of_code']} |
| Classes | {metrics['classes']} |
| Functions | {metrics['functions']} |
| Imports | {metrics['imports']} |

## Issues Found: {len(issues)}

"""

    severity_order = {'CRITICAL': 0, 'HIGH': 1, 'MEDIUM': 2, 'LOW': 3}
    issues.sort(key=lambda x: severity_order.get(x['severity'], 4))

    for issue in issues:
        emoji = {'CRITICAL': '🚨', 'HIGH': '⚠️', 'MEDIUM': '⚡', 'LOW': 'ℹ️'}.get(issue['severity'], '•')
        report += f"""### {emoji} {issue['severity']} - Line {issue['line']}
**Issue:** {issue['issue']}
**Fix:** {issue['fix']}

"""

    # Summary
    critical = sum(1 for i in issues if i['severity'] == 'CRITICAL')
    high = sum(1 for i in issues if i['severity'] == 'HIGH')
    medium = sum(1 for i in issues if i['severity'] == 'MEDIUM')

    report += f"""## Summary
- 🚨 Critical Issues: {critical}
- ⚠️ High Issues: {high}
- ⚡ Medium Issues: {medium}

## Recommendations
1. **Immediate:** Fix SQL injection vulnerabilities
2. **Priority:** Implement proper password hashing
3. **Short-term:** Extract hardcoded configuration
4. **Long-term:** Add input validation and error handling
"""

    with open(REPORT_FILE, 'w') as f:
        f.write(report)

    print(f"✅ Code Quality Analysis Complete")
    print(f"📄 Report saved to: {REPORT_FILE}")
    return 0

if __name__ == '__main__':
    sys.exit(main())
EOF
