-- PostgreSQL Index Examples

-- 1. B-Tree Index (default, good for most use cases)
CREATE INDEX idx_users_email ON users USING btree (email);

-- 2. Hash Index (memory-only in older PG, persistent since PG10)
CREATE INDEX idx_users_hash ON users USING hash (email);

-- 3. GiST Index (for geometric and range types)
CREATE INDEX idx_locations_gist ON locations USING gist (geom);
CREATE INDEX idx_events_during ON events USING gist (event_period);

-- 4. GIN Index (for arrays, jsonb, full-text)
CREATE INDEX idx_posts_tags ON posts USING gin (tags);
CREATE INDEX idx_products_attrs ON products USING gin (attributes jsonb_path_ops);

-- 5. BRIN Index (for large, naturally ordered tables)
CREATE INDEX idx_logs_timestamp ON logs USING brin (created_at);

-- 6. SP-GiST (space-partitioned GiST)
CREATE INDEX idx_quadtree ON locations USING spgist (geom);

-- 7. Partial Index (only index relevant rows)
CREATE INDEX idx_orders_active ON orders (created_at)
  WHERE status = 'active';

-- 8. Expression Index (index computed values)
CREATE INDEX idx_users_email_lower ON users (lower(email));

-- 9. Composite Index with range
