import json
from typing import Dict, Any, Optional
from datetime import datetime


class APIResponseValidator:
    """Validates API responses against expected schema."""

    REQUIRED_FIELDS = {
        "user": ["id", "email", "created_at"],
        "order": ["id", "status", "total", "created_at"],
        "error": ["code", "message"]
    }

    @classmethod
    def validate_user(cls, data: Dict[str, Any]) -> bool:
        """Validate user object has required fields."""
        for field in cls.REQUIRED_FIELDS["user"]:
            if field not in data:
                raise AssertionError(f"User missing required field: {field}")
        cls._validate_iso_date(data["created_at"])
        return True

    @classmethod
    def validate_error(cls, data: Dict[str, Any]) -> bool:
        """Validate error response format."""
        if "error" not in data:
            raise AssertionError("Error response missing 'error' key")

        error = data["error"]
        for field in cls.REQUIRED_FIELDS["error"]:
            if field not in error:
                raise AssertionError(f"Error missing required field: {field}")
        return True

    @classmethod
    def _validate_iso_date(cls, date_str: str) -> None:
        """Validate ISO 8601 date string."""
        try:
            datetime.fromisoformat(date_str.replace('Z', '+00:00'))
        except ValueError:
            raise AssertionError(f"Invalid ISO 8601 date: {date_str}")


class RequestBuilder:
    """Builds API requests with proper formatting."""

    def __init__(self, base_url: str, auth_token: Optional[str] = None):
        self.base_url = base_url.rstrip('/')
        self.token = auth_token
        self.headers = {
            "Content-Type": "application/json",
            "Accept": "application/json"
        }
        if auth_token:
            self.headers["Authorization"] = f"Bearer {auth_token}"

    def get(self, path: str, params: Optional[Dict] = None) -> Dict:
        """Build GET request parameters."""
        return {
            "method": "GET",
            "url": f"{self.base_url}{path}",
            "headers": self.headers,
            "params": params or {}
        }

    def post(self, path: str, data: Dict) -> Dict:
        """Build POST request parameters."""
        return {
            "method": "POST",
            "url": f"{self.base_url}{path}",
            "headers": self.headers,
            "json": data
        }

    def put(self, path: str, data: Dict) -> Dict:
        """Build PUT request parameters."""
        return {
            "method": "PUT",
            "url": f"{self.base_url}{path}",
            "headers": self.headers,
            "json": data
        }

    def delete(self, path: str) -> Dict:
        """Build DELETE request parameters."""
        return {
            "method": "DELETE",
            "url": f"{self.base_url}{path}",
            "headers": self.headers
        }


class PaginationHelper:
    """Helpers for testing pagination."""

    @staticmethod
    def calculate_expected_pages(total: int, per_page: int) -> int:
        """Calculate expected number of pages."""
        return (total + per_page - 1) // per_page

    @staticmethod
    def get_offset(page: int, per_page: int) -> int:
        """Calculate offset from page number."""
        return (page - 1) * per_page

    @staticmethod
    def validate_meta(meta: Dict[str, Any]) -> None:
        """Validate pagination metadata."""
        required = ["page", "per_page", "total", "total_pages"]
        for field in required:
            assert field in meta, f"Pagination meta missing {field}"

        calculated_pages = PaginationHelper.calculate_expected_pages(
            meta["total"], meta["per_page"]
        )
        assert meta["total_pages"] == calculated_pages
        assert meta["page"] >= 1
