import { useState } from 'react'

export interface User {
  id: string
  name: string
  email: string
  role: 'admin' | 'user' | 'guest'
}

export interface UserProfileProps {
  user: User
  onEdit: (user: User) => void
  isLoading?: boolean
}

export function UserProfile({ user, onEdit, isLoading = false }: UserProfileProps) {
  const [isEditing, setIsEditing] = useState(false)
  const [editedName, setEditedName] = useState(user.name)
  const [editedEmail, setEditedEmail] = useState(user.email)

  const handleSave = () => {
    onEdit({
      ...user,
      name: editedName,
      email: editedEmail,
    })
    setIsEditing(false)
  }

  const handleCancel = () => {
    setEditedName(user.name)
    setEditedEmail(user.email)
    setIsEditing(false)
  }

  if (isLoading) {
    return (
      <div data-testid="user-profile-loading" className="user-profile user-profile--loading">
        <div className="user-profile__skeleton" data-testid="skeleton-name" />
        <div className="user-profile__skeleton" data-testid="skeleton-email" />
        <div className="user-profile__skeleton" data-testid="skeleton-role" />
      </div>
    )
  }

  if (isEditing) {
    return (
      <div data-testid="user-profile-editing" className="user-profile user-profile--editing">
        <div className="user-profile__field">
          <label htmlFor="edit-name">Name:</label>
          <input
            id="edit-name"
            type="text"
            value={editedName}
            onChange={e => setEditedName(e.target.value)}
            data-testid="edit-name-input"
          />
        </div>
        <div className="user-profile__field">
          <label htmlFor="edit-email">Email:</label>
          <input
            id="edit-email"
            type="email"
            value={editedEmail}
            onChange={e => setEditedEmail(e.target.value)}
            data-testid="edit-email-input"
          />
        </div>
        <div className="user-profile__actions">
          <button onClick={handleSave} data-testid="save-button">
            Save
          </button>
          <button onClick={handleCancel} data-testid="cancel-button">
            Cancel
          </button>
        </div>
      </div>
    )
  }

  return (
    <div data-testid="user-profile" className="user-profile">
      <h3 data-testid="user-name">{user.name}</h3>
      <p data-testid="user-email">{user.email}</p>
      <span data-testid="user-role" className={`user-profile__role user-profile__role--${user.role}`}>
        {user.role}
      </span>
      <button onClick={() => setIsEditing(true)} data-testid="edit-button">
        Edit
      </button>
    </div>
  )
}
