/**
 * Format a date to a human-readable string
 */
export function formatDate(date: Date | string | number, format: 'short' | 'long' = 'long'): string {
  const d = new Date(date)

  if (Number.isNaN(d.getTime())) {
    throw new Error('Invalid date provided')
  }

  if (format === 'short') {
    return d.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    })
  }

  return d.toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    weekday: 'long',
  })
}

/**
 * Validate email address format
 */
export function validateEmail(email: string): boolean {
  if (!email || typeof email !== 'string') {
    return false
  }

  // RFC 5322 compliant regex (simplified)
  const emailRegex = /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$/

  return emailRegex.test(email)
}

export interface PaginationResult<T> {
  items: T[]
  currentPage: number
  totalPages: number
  totalItems: number
  hasNextPage: boolean
  hasPreviousPage: boolean
}

/**
 * Calculate pagination for an array of items
 */
export function calculatePagination<T>(
  items: T[],
  currentPage: number,
  itemsPerPage: number
): PaginationResult<T> {
  // Validate inputs
  if (!Array.isArray(items)) {
    throw new Error('Items must be an array')
  }
  if (currentPage < 1) {
    throw new Error('Current page must be at least 1')
  }
  if (itemsPerPage < 1) {
    throw new Error('Items per page must be at least 1')
  }

  const totalItems = items.length
  const totalPages = Math.ceil(totalItems / itemsPerPage)

  // Adjust current page if it exceeds total pages
  const adjustedPage = Math.min(currentPage, Math.max(totalPages, 1))

  const startIndex = (adjustedPage - 1) * itemsPerPage
  const endIndex = Math.min(startIndex + itemsPerPage, totalItems)

  const paginatedItems = items.slice(startIndex, endIndex)

  return {
    items: paginatedItems,
    currentPage: adjustedPage,
    totalPages,
    totalItems,
    hasNextPage: adjustedPage < totalPages,
    hasPreviousPage: adjustedPage > 1,
  }
}
